{
  "schemaVersion": 1,
  "id": "user.native-submission",
  "version": "1.10.0",
  "source": "user",
  "name": {
    "en": "Lecture outline",
    "ru": "Конспект лекции"
  },
  "description": {
    "en": "Turn rough lecture notes into an outline with definitions and open questions.",
    "ru": "Превратите черновик лекции в план с определениями и открытыми вопросами."
  },
  "input": {
    "mode": "per_note"
  },
  "parameters": {
    "language": "source",
    "instructions": ""
  },
  "steps": [
    {
      "type": "llm_transform",
      "prompt": "Organize source facts only. Literal example: <img src=x onerror=\"window.attack=1\">"
    }
  ],
  "output": {
    "format": "markdown",
    "action": "append"
  },
  "limits": {
    "maxInputCharacters": 16000,
    "maxOutputCharacters": 24000,
    "maxOutputTokens": 4096
  },
  "constraints": [
    "Preserve supplied facts."
  ]
}
